import{_ as n,C as o,o as r,c as i,a2 as t,E as a}from"./chunks/framework.CGSzHL4z.js";const y=JSON.parse('{"title":"Easing and curves","description":"","frontmatter":{},"headers":[],"relativePath":"features/easing.md","filePath":"features/easing.md","lastUpdated":1792710555000}'),d={name:"features/easing.md"};function h(l,e,g,c,p,u){const s=o("Screenshot");return r(),i("div",null,[e[0]||(e[0]=t('<h1 id="easing-and-curves" tabindex="-1">Easing and curves <a class="header-anchor" href="#easing-and-curves" aria-label="Permalink to &quot;Easing and curves&quot;">​</a></h1><p>An ease sets how a value travels from one key to the next: slow at first, fast at the end, overshooting and settling back. AcesMotion gives you three places to set it. The <strong>Ease window</strong> floats beside your work and follows the selection, the <strong>Ease view</strong> sits in the Timeline, and the Library&#39;s <strong>Easing</strong> tab holds every preset. All three share the same presets, including the ones you save.</p><h2 id="the-ease-window" tabindex="-1">The Ease window <a class="header-anchor" href="#the-ease-window" aria-label="Permalink to &quot;The Ease window&quot;">​</a></h2><p>Select keys and press <code>E</code>. The key menu&#39;s <strong>Ease...</strong> and the Ease button in the track column header open it too. It opens only when the selected keys have a next key to ease toward; otherwise the status bar says why.</p>',4)),a(s,{name:"feat-ease",caption:"The Ease window. Dragging the second handle reshapes the curve while the X2 and Y2 fields follow; Recent presets and the preset grid sit below."}),e[1]||(e[1]=t('<p>From the top, the window holds:</p><table tabindex="0"><thead><tr><th>Part</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Ease</strong> header</td><td>The range being eased, and a <strong>+</strong> that saves the curve the selection shares as a preset</td></tr><tr><td><strong>Curve</strong></td><td>A canvas with two handles and the <strong>X1</strong>, <strong>Y1</strong>, <strong>X2</strong>, <strong>Y2</strong> fields. Dragging a handle updates the curve, the fields and the scene as you go, and lands as one undo step when you let go</td></tr><tr><td><strong>Recent</strong></td><td>The last 8 presets you applied anywhere, newest first</td></tr><tr><td>Search and presets</td><td>Every preset, your saved ones first. One click applies a card</td></tr></tbody></table><p>The window stays open and follows your selection, and Studio remembers where it sits. The <strong>Curve</strong> section folds and stays folded if you only want presets. With no segment selected everything greys out under &quot;Select keys to ease them.&quot; Press <code>Esc</code>, <code>E</code> again, or its close button to close it.</p><h2 id="the-ease-view" tabindex="-1">The Ease view <a class="header-anchor" href="#the-ease-view" aria-label="Permalink to &quot;The Ease view&quot;">​</a></h2><p>Press <code>Tab</code> in the Timeline to cycle <strong>Dope sheet</strong>, <strong>Ease view</strong>, <strong>Channels view</strong>. In Split layout the <strong>Ease</strong> tab under the search box opens it under the dope rows.</p><p>The Ease view draws one progress curve for everything selected:</p><ul><li>A summary bar names what you&#39;re easing (&quot;r6 · 6 channels · f0 to f15&quot;) with chips for the segment count and whether they share an ease (<strong>Bezier</strong>, <strong>Same ease</strong>, <strong>Custom ease</strong> or <strong>Mixed</strong>).</li><li>The canvas has two handles. X stays between 0 and 1, <code>Shift</code> snaps to 0.05 and <code>Alt</code> ignores snapping. Dragging a handle past 100% washes the overshoot zone.</li><li>The <strong>Handles</strong> column has the X1, Y1, X2, Y2 fields and a Preset dropdown.</li><li><strong>Save as preset</strong> keeps the curve, and <strong>Reset</strong> puts the segments back to Cubic with Auto tangents.</li></ul><p>It works on the selected keys&#39; segments. With no keys selected, it eases the segment under the playhead on every channel of the selected rows. A drag previews live in the viewport and lands as one undo step (&quot;Set ease on N channels&quot;). Cubic segments shaped by tangents read <strong>Custom</strong>.</p><h2 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to &quot;Presets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Presets</th></tr></thead><tbody><tr><td>Basic</td><td>Linear, In and Out (soft, medium, strong), Back, Snap, Anticipate, Elastic, Bounce, Step</td></tr><tr><td>Principles</td><td>Slow in out, Wind up, Overshoot, Full swing, Heavy, Light, Strike, Pop, Hang time, Moving hold</td></tr><tr><td>Families</td><td>Sine, Quad, Cubic, Quart, Quint, Expo, Circ and Back, each as In, Out and In out</td></tr><tr><td>Out in</td><td>Soft, medium, strong</td></tr><tr><td>Saved</td><td>The ones you saved</td></tr></tbody></table><p>Each Principles preset&#39;s tooltip says when to use it.</p><h2 id="the-library-s-easing-tab" tabindex="-1">The Library&#39;s Easing tab <a class="header-anchor" href="#the-library-s-easing-tab" aria-label="Permalink to &quot;The Library&#39;s Easing tab&quot;">​</a></h2><p>The Library&#39;s <strong>Easing</strong> tab lists the same presets under <strong>Built in</strong> and <strong>Saved</strong>. Click a card to select it, then double click it or press <strong>Apply to selection</strong> to put it on the selected keys&#39; segments. <strong>Save current curve</strong> keeps the ease the selection shares.</p>',13)),a(s,{name:"lib-easing",caption:"The Library's Easing tab: Built in and Saved, the preset cards from Linear and In soft through Back, Snap, Anticipate, Elastic, Bounce and Step, the Principles group, and Apply to selection."}),e[2]||(e[2]=t('<p>Under <strong>Saved</strong>, right click a preset to rename it or delete it. <strong>Export presets...</strong> and <strong>Import presets</strong> share them with your team as a file (see <a href="./library#sharing-presets">The Library</a>).</p><h2 id="eases-on-single-keys" tabindex="-1">Eases on single keys <a class="header-anchor" href="#eases-on-single-keys" aria-label="Permalink to &quot;Eases on single keys&quot;">​</a></h2><p>The Key panel in the Inspector shows a key&#39;s <strong>Interpolation</strong>: Constant, Linear, Cubic, Eased or Bezier.</p><table tabindex="0"><thead><tr><th>Interpolation</th><th>Extra fields</th></tr></thead><tbody><tr><td>Cubic</td><td>Tangent mode, In slope and Out slope</td></tr><tr><td>Eased</td><td>Style and Direction</td></tr><tr><td>Bezier</td><td>Preset, a small ease preview you can drag, and X1 Y1 X2 Y2</td></tr></tbody></table><p>A new Bezier key starts from <strong>Settings &gt; Curves &gt; Default ease preset</strong>. The curve toolbar in the Channels view also has 8 preset tiles (Linear, Sine in-out, Quad in, Cubic in, Back in-out, Elastic in, Bounce out, Step). Those bake their shape into the selected segments as Cubic keys, so you can edit the tangents afterwards.</p><h2 id="other-things-that-ease" tabindex="-1">Other things that ease <a class="header-anchor" href="#other-things-that-ease" aria-label="Permalink to &quot;Other things that ease&quot;">​</a></h2><ul><li><strong>Motion Warp trips.</strong> Select a warp bar with no keys selected and press <code>E</code>. The Ease window re-times the trip along the same path.</li><li><strong>Number sequences.</strong> While a sequence editor is open, applying a Library ease lays it on the selected segment as up to 8 new points.</li><li><strong>Driver mapping.</strong> A driver&#39;s <strong>Shape</strong> uses the ease presets to curve its mapping.</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Deleting a saved preset asks first, because presets live in your plugin settings and Ctrl+Z can&#39;t bring them back.</li><li>The Recent list fills from every place you apply a preset, so your favourite eases end up one click away in the Ease window.</li></ul><h2 id="compared-to-roblox-s-animation-editor" tabindex="-1">Compared to Roblox&#39;s Animation Editor <a class="header-anchor" href="#compared-to-roblox-s-animation-editor" aria-label="Permalink to &quot;Compared to Roblox&#39;s Animation Editor&quot;">​</a></h2><p>Roblox&#39;s Animation Editor eases a rig&#39;s keyframes with easing styles and directions and has its own curve editor. In AcesMotion the same eases work on every track the scene holds, so a camera&#39;s FieldOfView, a light&#39;s Brightness or a Motion Warp&#39;s trip can ease with the same Wind up or Bounce you use on a joint.</p>',11))])}const m=n(d,[["render",h]]);export{y as __pageData,m as default};
